create table public.ketvoice_devices ( user_id uuid not null references auth.users(id) on delete cascade, device_id text not null check (device_id ~ '^[A-Za-z0-9-]{8,64}$'), name text not null default '' check (char_length(name) <= 40 and name !~ '[[:cntrl:]]'), kind text not null default 'phone' check (kind in ('phone', 'tablet', 'quest', 'pc', 'web')), session_id uuid, state jsonb not null default '{}'::jsonb check (jsonb_typeof(state) = 'object' and pg_column_size(state) <= 65536), revoked_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (user_id, device_id) );
create index ketvoice_devices_updated on public.ketvoice_devices (user_id, updated_at desc);
create function public.ketvoice_devices_stamp() returns trigger language plpgsql set search_path = '' as $$ declare revoking boolean := coalesce(current_setting('ketvoice.revoking', true), '') = 'on'; begin if tg_op = 'INSERT' then if (select count(*) from public.ketvoice_devices d where d.user_id = new.user_id) >= 50 then raise exception 'Too many devices' using errcode = '54000'; end if; new.created_at := now(); if not revoking then new.revoked_at := null; end if; else if new.user_id <> old.user_id or new.device_id <> old.device_id then raise exception 'A device keeps its owner and id' using errcode = '42501'; end if; new.created_at := old.created_at; if not revoking then new.revoked_at := case when new.session_id is distinct from old.session_id then null else old.revoked_at end; end if; end if; new.updated_at := now(); return new; end $$;
create trigger ketvoice_devices_stamp before insert or update on public.ketvoice_devices for each row execute function public.ketvoice_devices_stamp();
alter table public.ketvoice_devices enable row level security;
revoke all on public.ketvoice_devices from public, anon, authenticated;
grant select, insert, update, delete on public.ketvoice_devices to authenticated;
grant all on public.ketvoice_devices to service_role;
create policy ketvoice_devices_own_select on public.ketvoice_devices for select to authenticated using ((select auth.uid()) = user_id);
create policy ketvoice_devices_own_insert on public.ketvoice_devices for insert to authenticated with check ((select auth.uid()) = user_id);
create policy ketvoice_devices_own_update on public.ketvoice_devices for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy ketvoice_devices_own_delete on public.ketvoice_devices for delete to authenticated using ((select auth.uid()) = user_id);
create function public.ketvoice_revoke_device(p_user uuid, p_device text, p_caller_session uuid) returns text language plpgsql security definer set search_path = '' as $$ declare sid uuid; begin select d.session_id into sid from public.ketvoice_devices d where d.user_id = p_user and d.device_id = p_device; if not found then return 'not_found'; end if; if sid is not null and sid = p_caller_session then return 'self'; end if; perform set_config('ketvoice.revoking', 'on', true); if sid is not null then delete from auth.sessions s where s.id = sid and s.user_id = p_user; end if; update public.ketvoice_devices set revoked_at = now() where user_id = p_user and device_id = p_device; perform set_config('ketvoice.revoking', '', true); return 'revoked'; end $$;
revoke all on function public.ketvoice_revoke_device(uuid, text, uuid) from public, anon, authenticated;
grant execute on function public.ketvoice_revoke_device(uuid, text, uuid) to service_role;
create table public.ketvoice_device_links ( code text primary key check (code ~ '^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{8}$'), secret_hash text not null check (secret_hash ~ '^[0-9a-f]{64}$'), device_name text not null default '' check (char_length(device_name) <= 40 and device_name !~ '[[:cntrl:]]'), device_kind text not null default 'pc' check (device_kind in ('phone', 'tablet', 'quest', 'pc', 'web')), created_at timestamptz not null default now(), expires_at timestamptz not null default now() + interval '5 minutes' check (expires_at <= created_at + interval '10 minutes'), approved_by uuid references auth.users(id) on delete cascade, approved_at timestamptz, denied_at timestamptz, consumed_at timestamptz, last_poll_at timestamptz );
create index ketvoice_device_links_expiry on public.ketvoice_device_links (expires_at);
alter table public.ketvoice_device_links enable row level security;
revoke all on public.ketvoice_device_links from public, anon, authenticated;
grant all on public.ketvoice_device_links to service_role;
create table public.ketvoice_lastfm_links ( user_id uuid primary key references auth.users(id) on delete cascade, username text check (username is null or (char_length(username) between 1 and 64 and username !~ '[[:cntrl:]]')), session_key text check (session_key is null or char_length(session_key) between 8 and 128), pending_token text check (pending_token is null or char_length(pending_token) between 8 and 128), pending_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
alter table public.ketvoice_lastfm_links enable row level security;
revoke all on public.ketvoice_lastfm_links from public, anon, authenticated;
grant all on public.ketvoice_lastfm_links to service_role;
